// hotel.checkin → guest welcome message (room, nights, checkout date).
const b = $input.first().json.body || {};
const d = b.data || {};
const checkin = new Date(d.checkedInAt || Date.now());
const out = new Date(checkin.getTime() + (Number(d.nights)||0)*86400000);
const fmt = (x) => x.toISOString().slice(0,10);
const summary = 'Welcome' + (d.guest ? ', ' + d.guest : '') + '! Room ' + d.room + ' is ready.'
  + (d.nights ? ' Checkout ' + fmt(out) + ' (' + d.nights + ' night' + (d.nights===1?'':'s') + ').' : '')
  + ' Dial 0 for room service.';
return [{ json: { event: b.event, room: d.room, guest: d.guest, checkoutDate: fmt(out), summary } }];
